messages.content:
```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "pelaku-ekonomi-run", title: "Peran Pelaku Ekonomi Run", seed: "pelaku-ekonomi-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "IPS / Ekonomi",
    concept: "Peran rumah tangga konsumen, rumah tangga produsen, dan pemerintah dalam kegiatan ekonomi",
    objectives: ["Mengelompokkan kegiatan ekonomi berdasarkan pelakunya"],
    misconceptions: ["Pemerintah hanya mengatur, tidak melakukan kegiatan ekonomi"],
    mode: "category",
    categories: [
      { id: "konsumen",  label: "Rumah Tangga Konsumen", color: "#2F80ED" },
      { id: "produsen",  label: "Rumah Tangga Produsen", color: "#3FA34D" },
      { id: "pemerintah", label: "Pemerintah",           color: "#E5484D" }
    ],
    items: [
      { id: "beli-pasar",    label: "Membeli barang di pasar", category: "konsumen",   explain: "RTK memakai barang dan jasa untuk memenuhi kebutuhan hidupnya." },
      { id: "bayar-pajak",   label: "Membayar pajak",          category: "konsumen",   explain: "RTK menyerahkan sebagian penghasilan kepada pemerintah." },
      { id: "menabung",      label: "Menabung di bank",        category: "konsumen",   explain: "RTK menyisihkan penghasilan untuk konsumsi masa depan." },
      { id: "produksi",      label: "Memproduksi barang",      category: "produsen",   explain: "RTP mengolah faktor produksi menjadi barang dan jasa." },
      { id: "upah",          label: "Membayar upah karyawan",  category: "produsen",   explain: "RTP memberi balas jasa atas tenaga kerja yang dipakai." },
      { id: "bahan-baku",    label: "Membeli bahan baku",      category: "produsen",   explain: "RTP membeli input untuk menjalankan kegiatan produksi." },
      { id: "tarik-pajak",   label: "Menarik pajak",           category: "pemerintah", explain: "Pemerintah memungut pajak dari rumah tangga dan perusahaan." },
      { id: "jalan-raya",    label: "Membangun jalan raya",    category: "pemerintah", explain: "Pemerintah menyediakan fasilitas publik untuk masyarakat." },
      { id: "subsidi",       label: "Memberi subsidi",         category: "pemerintah", explain: "Pemerintah menyalurkan bantuan untuk meringankan harga." },
      { id: "belanja-negara", label: "Belanja barang dan jasa", category: "pemerintah", explain: "Pemerintah juga mengonsumsi barang dan jasa, bukan hanya mengatur." },
      { id: "bumn",          label: "Mengelola BUMN",          category: "pemerintah", explain: "Pemerintah menjalankan badan usaha milik negara sebagai produsen." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "peti",   w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "palang", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game edukasi Endless Runner ini menguji pemain memilah kegiatan ekonomi sesuai pelakunya (konsumen, produsen, pemerintah) dengan tema Clean Modern dan tempo Normal. Asumsi penting: item "Belanja barang dan jasa" serta "Mengelola BUMN" sengaja dimasukkan sebagai penekan miskonsepsi bahwa pemerintah hanya mengatur.
